<?php
require __DIR__.'/../includes/header.php';$u=require_role('shelter');$s=db()->prepare('SELECT * FROM shelters WHERE user_id=?');$s->execute([$u['id']]);$sh=$s->fetch();if(!$sh){redirect('shelter/index.php');}$q=db()->prepare('SELECT r.*,a.status assignment_status,u.name volunteer_name FROM rescue_assignments a JOIN stray_reports r ON r.id=a.report_id JOIN users u ON u.id=a.volunteer_id WHERE a.shelter_id=? ORDER BY r.created_at DESC');$q->execute([$sh['id']]);$rows=$q->fetchAll();?>
<div class="section-head"><div><h1>Rescue reports for <?=e($sh['name'])?></h1><p class="muted">Reports assigned to your shelter as a safe destination.</p></div></div><?php if(!$rows):?><div class="panel empty">No rescue reports have been routed to your shelter.</div><?php else:?><div class="grid"><?php foreach($rows as $r):?><div class="panel"><span class="badge <?=e($r['status'])?>"><?=e($r['status'])?></span><h3><?=e($r['location'])?></h3><p><?=nl2br(e($r['description']))?></p><p class="small muted">Volunteer: <?=e($r['volunteer_name'])?> &middot; Assignment: <?=e($r['assignment_status'])?></p></div><?php endforeach;?></div><?php endif;?>
<?php require __DIR__.'/../includes/footer.php'; ?>
